import {createSupportUI} from "./support-ui.js";
import {createRoleUI} from "./role-ui.js";
const app=document.querySelector('#app'), modal=document.querySelector('#modal'), modalContent=document.querySelector('#modal-content');
const state={ctx:null,route:'overview',data:null,search:'',filter:'all',page:0,dirty:false,roster:null,catalog:'Course',loading:false,term:'',terms:[],dateScope:'all',lastHash:null,rosterSearch:'',rosterOnlyPending:false};
const paths={cap:'m3 9 9-5 9 5-9 5-9-5zm4 3v6q5 5 10 0v-6m4-3v9',grid:'M3 3h7v7H3zm11 0h7v7h-7zM3 14h7v7H3zm11 0h7v7h-7z',book:'M4 4h7q1 0 1 2v15q0-2-2-2H4zm16 0h-7q-1 0-1 2v15q0-2 2-2h6z',calendar:'M4 5h16v16H4zM7 3v4m10-4v4M4 10h16m-12 4h2m4 0h2m-8 3h2',users:'M16 21v-2q0-4-5-4t-5 4v2m5-10a4 4 0 1 0 0-8 4 4 0 0 0 0 8m7-7a4 4 0 0 1 0 7m3 10v-2q0-3-3-4',alert:'m12 3 10 18H2L12 3zm0 6v5m0 3v.1',heart:'M20 5q-5-5-8 1-4-6-8-1-5 6 8 15 13-9 8-15',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8m-2-6h4l1 3 3 1 3 3-2 3 1 3-3 3-3-1-2 3-4-1-1-3-3-1-1-4 2-2-1-3 3-3 3 1z',search:'M21 21l-5-5m2-6a7 7 0 1 0-14 0 7 7 0 0 0 14 0',arrow:'M5 12h14m-5-5 5 5-5 5',chevron:'m9 5 7 7-7 7',plus:'M12 5v14M5 12h14',logout:'M9 5H4v14h5m0-7h12m-4-4 4 4-4 4',check:'m5 12 4 4 10-10',clock:'M12 8v5l3 2m6-3a9 9 0 1 0-18 0 9 9 0 0 0 18 0',bell:'M5 17h14l-2-4V8q0-5-5-5T7 8v5l-2 4zm5 3h4',close:'m6 6 12 12M6 18 18 6',menu:'M4 6h16M4 12h16M4 18h16',download:'M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5',shield:'m12 3 8 3v6q0 6-8 10-8-4-8-10V6l8-3zm-4 9 3 3 5-6',trend:'m3 17 6-6 4 4 8-10m-6 0h6v6',note:'M5 3h14v18H5zm4 5h6m-6 4h6m-6 4h4',eye:'M2 12q10-14 20 0-10 14-20 0zm10-3a3 3 0 1 0 0 6 3 3 0 0 0 0-6',mail:'M3 5h18v14H3zm0 0 9 8 9-8',phone:'M6 3h4l1 5-3 2q2 5 6 6l2-3 5 1v4q0 6-10-1T6 3',refresh:'M20 8a9 9 0 1 0 1 7m-1-12v5h-5'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.note}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tr={Good:'Ổn định',Warning:'Nhắc nhở',Critical:'Nguy hiểm',Barred:'Cấm thi',Present:'Có mặt',Absent:'Vắng mặt',Late:'Đi muộn',Open:'Chưa xử lý','In Progress':'Đang hỗ trợ',Resolved:'Đã giải quyết',Scheduled:'Chưa chốt',Completed:'Đã hoàn thành',Cancelled:'Đã hủy',Postponed:'Đã hoãn',Active:'Đang hoạt động',Inactive:'Ngừng hoạt động',Enrolled:'Đang học',Planned:'Dự kiến','In Progress Class':'Đang học',Phone:'Điện thoại',Email:'Email',Meeting:'Gặp trực tiếp',Online:'Trực tuyến',Other:'Khác',Reached:'Đã liên hệ','No Response':'Chưa phản hồi',Rescheduled:'Hẹn lại',Monitoring:'Đang theo dõi',Improved:'Đã cải thiện',Escalated:'Chuyển hỗ trợ',Closed:'Kết thúc',Pending:'Chờ xử lý','Course-Level':'Theo môn học','Behavioral-Level':'Hành vi học tập'};
const text=v=>tr[v]||v||'—';
const badge=(v,label)=>`<span class="badge ${esc(String(v||'').replaceAll(' ',''))}">${esc(label||text(v))}</span>`;
const short=v=>String(v||'').replace('DEMO-20261019-','').replace(/^.* - DEMO - /,'').replace(/^DEMO-20261019 - /,'');
const initials=n=>(String(n||'S').split(' ').filter(Boolean).slice(-2).map(x=>x[0]).join('')).toUpperCase();
const avatar=(n,i=0)=>`<span class="avatar a${i%5}">${esc(initials(n))}</span>`;
const date=(v,long=false)=>{if(!v)return'—';const d=new Date(String(v).replace(' ','T'));return Number.isNaN(d.getTime())?esc(v):d.toLocaleDateString('vi-VN',long?{day:'numeric',month:'long',year:'numeric'}:{day:'2-digit',month:'2-digit',year:'numeric'});};
const time=v=>{if(!v)return'—';const[h,m]=String(v).split(':');return`${h.padStart(2,'0')}:${(m||'00').padStart(2,'0')}`;};
const num=v=>Number(v||0).toLocaleString('vi-VN',{maximumFractionDigits:1});
function toast(message,error=false){const el=document.querySelector('#toast');el.textContent=message;el.className=`show${error?' error':''}`;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.className='',4500);}
async function request(method,data={},verb='GET'){
 const requestUser=state.ctx?.user;
 const termMethods=new Set(['list_offerings','list_sessions','list_students','list_interventions','get_student_detail','student_crm.api.get_advisor_dashboard','student_crm.support.list_cases','student_crm.support.list_corrections','student_crm.support.list_my_attendance','student_crm.support.get_support_dashboard','student_crm.experience.get_workbench']);
 if(verb==='GET'&&termMethods.has(method)){
   data={...data,academic_term:state.term||null};
   if(['list_offerings','list_interventions','student_crm.api.get_advisor_dashboard','student_crm.support.list_cases','student_crm.support.list_corrections','student_crm.support.list_my_attendance'].includes(method))data.status=state.filter||'all';
   if(method==='list_sessions')data.date_scope=state.dateScope||'all';
 }
 const url=new URL('/api/method/'+(['login','logout'].includes(method)||method.includes('.')?method:'student_crm.portal.'+method),location.origin);
 const options={method:verb,credentials:'same-origin',headers:{Accept:'application/json'}};
 if(verb==='GET')for(const[k,v]of Object.entries(data))if(v!==null&&v!==undefined)url.searchParams.set(k,v);
 if(verb==='POST'){options.headers['Content-Type']='application/json';if(state.ctx?.csrf_token)options.headers['X-Frappe-CSRF-Token']=state.ctx.csrf_token;options.body=JSON.stringify(data);}
 const response=await fetch(url,options);let body;try{body=await response.json();}catch{throw new Error('Máy chủ trả về dữ liệu không hợp lệ.');}
 if(!response.ok||body.exc_type){let message=body.message||body.exc_type||'Thao tác chưa thành công.';try{const list=JSON.parse(body._server_messages||'[]');if(list[0])message=JSON.parse(list[0]).message||message;}catch{}const error=new Error(String(message).replace(/<[^>]*>/g,''));error.type=body.exc_type;error.status=response.status;
   if(requestUser&&state.ctx?.user===requestUser&&(response.status===401||response.status===403)&&!await sessionIsActive()&&state.ctx?.user===requestUser){error.type='SessionExpired';error.status=401;expireSession();}
   throw error;}
 if(verb==='POST'&&method==='student_crm.support.mark_notification_read')refreshUnread();
 return body.message;
}
const roles=()=>state.ctx?.roles||{};
const canAdvise=()=>roles().advisor||roles().admin;
const roleName=()=>roles().admin?'Quản trị viên':roles().advisor?'Cố vấn học tập':roles().instructor?'Giảng viên':'Sinh viên';
const empty=(title='Chưa có dữ liệu',description='Dữ liệu sẽ xuất hiện khi được cập nhật trong hệ thống.')=>`<div class="empty">${icon('book')}<h3>${esc(title)}</h3><p>${esc(description)}</p></div>`;
const stat=(label,value,ico,foot,color='')=>`<div class="stat"><div class="stat-top"><span>${label}</span><span class="stat-icon ${color}">${icon(ico)}</span></div><div class="stat-number" data-stat="${esc(label)}">${Number.isFinite(Number(value))?num(value):esc(value)}</div><div class="stat-foot">${icon('trend')}${foot}</div></div>`;
const head=(title,subtitle,actions='',eyebrow='KHÔNG GIAN LÀM VIỆC')=>`<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="page-actions">${actions}</div></div>`;
const nameCell=(n,id,i=0)=>`<div class="flex">${avatar(n,i)}<div><div class="cell-name">${esc(n)}</div><div class="cell-sub">${esc(short(id))}</div></div></div>`;
const button=(label,action,cls='',ico='',attrs='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${attrs}>${ico?icon(ico):''}${label}</button>`;
const pageNames={cases:'Hồ sơ hỗ trợ',impact:'Hiệu quả hỗ trợ',corrections:'Sửa điểm danh','my-attendance':'Điểm danh của tôi',notifications:'Thông báo',quality:'Chất lượng dữ liệu',overview:'Tổng quan',courses:'Lớp học phần',sessions:'Lịch học & điểm danh',students:'Sinh viên',warnings:'Cảnh báo sớm',interventions:'Nhật ký can thiệp',catalog:'Danh mục hệ thống',settings:'Cấu hình cảnh báo',profile:'Hồ sơ của tôi',roster:'Điểm danh buổi học'};
function shell(){const r=roles();const links=[['overview','grid','Tổng quan',true],['courses','book','Lớp học phần',r.instructor],['sessions','calendar','Lịch học & điểm danh',r.instructor],['students','users','Sinh viên',canAdvise()],['warnings','alert','Cảnh báo sớm',canAdvise()],['interventions','heart','Nhật ký can thiệp',canAdvise()],['profile','users','Hồ sơ của tôi',r.student],['cases','heart','Hồ sơ hỗ trợ',canAdvise()],['impact','trend','Hiệu quả hỗ trợ',canAdvise()],['corrections','check','Sửa điểm danh',true],['my-attendance','calendar','Điểm danh của tôi',r.student],['notifications','bell','Thông báo',true],['quality','shield','Chất lượng dữ liệu',r.admin],['catalog','note','Danh mục hệ thống',r.admin],['settings','settings','Cấu hình cảnh báo',r.admin]].filter(x=>x[3]);
 app.innerHTML=`<aside class="sidebar"><a class="brand" href="#/overview"><span class="brandmark">${icon('cap')}</span><div><div class="brand-title">Student<span style="font-weight:400">CRM</span></div><div class="brand-sub">CAMPUS WORKSPACE</div></div></a><div class="workspace-chip"><span>${icon('book')}</span><span>Không gian đào tạo<br><strong >Đại học · Student CRM</strong></span></div><div class="nav-label">QUẢN LÝ HỌC TẬP</div><nav class="nav">${links.map(([route,ico,label])=>`<a href="#/${route}" data-route="${route}">${icon(ico)}${label}${route==='notifications'?'<span class="notification-count" data-unread hidden></span>':''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="support-card">${icon('shield')}<div style="margin-top:9px"><strong>Mỗi sinh viên đều quan trọng.</strong><p>Nhận diện sớm để đồng hành đúng lúc.</p></div></div><div class="user-side flex">${avatar(state.ctx.full_name)}<div><strong>${esc(state.ctx.full_name)}</strong><small>${roleName()}</small></div><button class="icon-button" data-action="logout" title="Đăng xuất" aria-label="Đăng xuất">${icon('logout')}</button></div></div></aside><main class="main"><header class="topbar"><div class="flex"><button class="icon-button mobile-menu" data-action="menu" aria-label="Mở menu">${icon('menu')}</button><div class="breadcrumb"><span>Không gian làm việc</span><span>/</span><strong id="crumb">Tổng quan</strong></div></div><div class="top-actions"><form class="top-search" id="global-search">${icon('search')}<input aria-label="Tìm kiếm trong hệ thống" placeholder="${canAdvise()?'Tìm sinh viên…':'Tìm môn hoặc lớp học…'}"></form><a class="icon-button notification-bell" href="#/notifications" aria-label="Thông báo">${icon('bell')}<span class="notification-count" data-unread hidden></span></a><span class="top-date">${date(state.ctx.today,true)}</span><button class="icon-button" data-action="refresh" title="Làm mới" aria-label="Làm mới">${icon('refresh')}</button>${avatar(state.ctx.full_name)}</div></header><div class="content" id="view"></div></main>`;
}
function login(error=''){clearTimeout(toast.timer);const notice=document.querySelector('#toast');if(notice){notice.className='';notice.textContent='';}clearTimeout(state.searchTimer);Object.assign(state,{ctx:null,data:null,dirty:false,modalDirty:false,modalBusy:0,loadToken:null,roster:null,rosterSearch:'',rosterOnlyPending:false,term:'',terms:[],search:'',filter:'all',page:0,lastHash:null,dateScope:'all',recordForm:null,rosterSaving:false});app.innerHTML=`<div class="login"><section class="login-story"><div class="brand"><span class="brandmark">${icon('cap')}</span><div><div class="brand-title">StudentCRM</div><div class="brand-sub">ĐỒNG HÀNH CÙNG SINH VIÊN</div></div></div><h1 class="story-title">Mỗi buổi học.<br>Một cơ hội<br><em>đồng hành.</em></h1><p class="story-copy">Kết nối điểm danh, nhận diện rủi ro và hỗ trợ sinh viên — trong một không gian làm việc.</p><div class="story-visual"><div class="between"><span class="eyebrow">NHÌN SỚM HƠN MỘT BƯỚC</span>${icon('trend')}</div><div class="mini-bars">${[45,62,54,85,60,92,40,75,90,100].map(h=>`<i style="height:${h}%"></i>`).join('')}</div><div class="between small" ><span>Chuyên cần</span><span>Cảnh báo sớm</span><span>Hỗ trợ kịp thời</span></div></div><div class="story-footer">STUDENT SUCCESS STARTS WITH CONNECTION.</div></section><section class="login-form-wrap"><form class="login-form" id="login-form"><span class="login-badge">${icon('shield')} CỔNG QUẢN LÝ ĐÀO TẠO</span><h1>Chào mừng trở lại.</h1><p>Đăng nhập để tiếp tục đồng hành cùng sinh viên.</p><div class="field"><label for="email">Tài khoản</label><input id="email" name="usr" autocomplete="username" required placeholder="Email hoặc Administrator"></div><div class="field"><label for="password">Mật khẩu</label><div class="password-wrap"><input id="password" name="pwd" type="password" autocomplete="current-password" required placeholder="Nhập mật khẩu của bạn"><button class="icon-button" data-action="password" type="button" aria-label="Hiện hoặc ẩn mật khẩu">${icon('eye')}</button></div></div><div class="login-error" id="login-error">${esc(error)}</div><button class="btn primary" type="submit">Đăng nhập ${icon('arrow')}</button><div class="login-divider"></div><div class="eyebrow">TRẢI NGHIỆM VỚI TÀI KHOẢN MẪU</div><div class="demo-roles"><button type="button" data-action="demo" data-user="demo.crm.faculty01@example.com">Cố vấn học tập</button><button type="button" data-action="demo" data-user="demo.crm.faculty04@example.com">Giảng viên</button><button type="button" data-action="demo" data-user="demo.crm.student001@example.com">Sinh viên</button></div><p class="login-note">Chọn vai trò để điền tài khoản. Mật khẩu mẫu được cung cấp riêng trong cuộc chat; không lưu trên Website.</p><div class="footer-note">Student CRM · Chuyên cần & thành công học tập</div></form></section></div>`;}
async function boot(){try{state.ctx=await request('get_context');state.terms=(await request('student_crm.experience.get_terms')).items;shell();if(!canAdvise()&&!roles().instructor)document.querySelector('#global-search')?.remove();await route();}catch(e){if(e.type!=='SessionExpired')login(e.status===502?e.message:'');}}
function progress(completed,total=20){return `<div class="progress"><span style="width:${Math.min(100,Number(completed||0)/Number(total||20)*100)}%"></span></div>`;}
function warningRows(rows){return rows.length?`<div class="table-wrap"><table><thead><tr><th>SINH VIÊN</th><th>MỨC ĐỘ</th><th>NGUYÊN NHÂN</th><th>TIẾN ĐỘ</th><th></th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${nameCell(r.student_name,r.student,i)}</td><td>${badge(r.severity)}</td><td><span class="cell-name" >${r.warning_type==='Behavioral-Level'?`${num(r.consecutive_sessions)} buổi vắng liên tiếp`:`Vắng ${num(r.absent_slots)}/${num(r.total_slots)} slot · ${num(r.absence_percentage)}%`}</span><div class="alert-type">${esc(r.course_name||text(r.warning_type))}</div></td><td>${badge(r.status)}</td><td><button class="icon-button" data-action="warning" data-id="${esc(r.name)}" title="Chi tiết cảnh báo" aria-label="Chi tiết cảnh báo">${icon('chevron')}</button></td></tr>`).join('')}</tbody></table></div>`:empty('Chưa có cảnh báo đang mở','Các tín hiệu cần hỗ trợ sẽ được tổng hợp tại đây.');}
function timeline(rows){return rows.length?`<div class="timeline">${rows.map(r=>`<div class="timeline-item"><strong>${esc(r.student_name||r.advisor_name)}</strong><p>${esc(r.summary)}</p><small>${date(r.contacted_at)} · ${esc(text(r.channel))}</small></div>`).join('')}</div>`:empty('Chưa có nhật ký','Bắt đầu hỗ trợ từ chi tiết một cảnh báo.');}
function advisorOverview(data){const s=data.summary.students,w=data.summary.warnings,total=s.total_students||0;const risk=s.critical+s.barred;let offset=0;const colors=['#4d8a6c','#e1c47d','#dda278','#ce7467'];const values=[s.good,s.warning,s.critical,s.barred];const gradient=values.map((v,i)=>{const start=offset;offset+=total?v/total*100:0;return`${colors[i]} ${start}% ${offset}%`;}).join(',');
 return head('Tổng quan học tập','Một góc nhìn rõ ràng để không bỏ lỡ sinh viên cần hỗ trợ.',`<span class="pill">${icon('calendar')} ${date(state.ctx.today)}</span>`,roles().admin?'GÓC NHÌN TOÀN HỆ THỐNG':'KHÔNG GIAN CỐ VẤN')+`<div class="stats">${stat('Sinh viên phụ trách',total,'users','Trong phạm vi được phân công')}${stat('Cần ưu tiên hỗ trợ',risk,'heart','Nguy hiểm và cấm thi','amber')}${stat('Cảnh báo đang mở',w.active_warnings,'alert',`${num(w.in_progress)} cảnh báo đang được hỗ trợ`,'red')}${stat('Sinh viên cấm thi',s.barred,'shield','Vắng vượt ngưỡng cho phép','blue')}</div><div class="dashboard-grid"><div class="stack"><div class="welcome-band"><div><h2>Can thiệp sớm, tạo nên thay đổi.</h2><p>${risk?`Có ${num(risk)} sinh viên cần được ưu tiên liên hệ. Một cuộc trò chuyện đúng lúc có thể giúp các bạn trở lại nhịp học tập.`:'Các sinh viên đang duy trì nhịp học tập ổn định. Tiếp tục theo dõi để hỗ trợ đúng lúc.'}</p></div><div class="welcome-icon">${icon('heart')}</div></div><section class="panel"><div class="panel-head between"><div><h2>Cảnh báo cần quan tâm</h2><p>Ưu tiên theo mức độ và thời điểm phát hiện</p></div><a class="link small" href="#/warnings">Xem tất cả ${icon('arrow')}</a></div>${warningRows(data.warnings.slice(0,6))}<div class="table-foot">${num(w.active_warnings)} cảnh báo đang hoạt động · Chỉ hiển thị dữ liệu thuộc phạm vi của bạn</div></section><section class="panel"><div class="panel-head between"><div><h2>Ưu tiên liên hệ hôm nay</h2><p>Sinh viên có nguy cơ cao cần được đồng hành</p></div><span class="pill">${num(risk)} sinh viên</span></div>${data.high_risk_students.slice(0,5).map((r,i)=>`<a href="#/students/${encodeURIComponent(r.student)}" class="risk-card flex">${avatar(r.student_name,i)}<div><div class="cell-name">${esc(r.student_name)}</div><div class="cell-sub">${esc(short(r.student))} · ${r.behavioral_absence_streak>=3?'Vắng liên tiếp qua nhiều môn':'Cần theo dõi chuyên cần'}</div></div><span style="margin-left:auto">${badge(r.risk_standing)}</span><span class="chevron">${icon('chevron')}</span></a>`).join('')||empty('Chưa có sinh viên nguy cơ cao')}</section></div><aside class="dashboard-right stack"><section class="panel"><div class="panel-head"><h2>Sức khỏe học tập</h2><p>Phân bố trạng thái sinh viên</p></div><div class="panel-body"><div class="donut-wrap"><div class="donut" style="background:conic-gradient(${total?gradient:'#edf2ee 0% 100%'})"><div class="donut-center"><strong>${num(total)}</strong><span>sinh viên</span></div></div></div><div class="legend">${['Good','Warning','Critical','Barred'].map((k,i)=>`<div class="legend-item"><i style="background:${colors[i]}"></i>${text(k)}<b>${num(values[i])}</b></div>`).join('')}</div></div></section><div class="behavior-box"><div class="flex"><span class="stat-icon">${icon('alert')}</span><h3 style="margin:0">Cảnh báo hành vi</h3></div><p><strong>${num(w.behavioral)} tín hiệu</strong> vắng liên tiếp qua nhiều môn đang cần được xác minh và hỗ trợ.</p></div><section class="panel"><div class="panel-head"><h2>Đồng hành gần đây</h2><p>Những kết nối đã được ghi nhận</p></div>${timeline(data.recent_interventions||[])}</section></aside></div>`;
}
function courseCards(items){return items.length?`<div class="course-grid">${items.map((c,i)=>`<article class="course-card"><div class="between"><span class="stat-icon ${i%3===1?'blue':i%3===2?'amber':''}">${icon('book')}</span><span class="pill">${esc(c.course)}</span></div><h2>${esc(c.course_name)}</h2><p>${esc(c.class_name||short(c.name))}</p><div class="flex small muted">${icon('users')}${num(c.students)} sinh viên <span style="margin-left:auto">${num(c.completed)}/${num(c.total_slots)} slot</span></div>${progress(c.completed,c.total_slots)}<div class="course-bottom between"><span class="small muted">${esc(c.room||'Chưa xếp phòng')}</span><a class="link small" href="#/sessions/${encodeURIComponent(c.name)}">Xem buổi học →</a></div></article>`).join('')}</div>`:empty('Chưa có lớp học phần','Các lớp được phân công sẽ xuất hiện tại đây.');}
function teacherOverview(data){const items=data.offerings||[],sessions=data.sessions||[];return head('Một ngày học tập hiệu quả.','Theo dõi lớp học và ghi nhận sự hiện diện của từng sinh viên.',`<a class="btn primary" href="#/sessions">${icon('calendar')} Mở sổ điểm danh</a>`,'KHÔNG GIAN GIẢNG VIÊN')+`<div class="stats">${stat('Lớp đang phụ trách',items.length,'book','Lớp học phần được phân công')}${stat('Lượt sinh viên đăng ký',items.reduce((a,b)=>a+Number(b.students),0),'users','Trong các lớp phụ trách','blue')}${stat('Slot đã chốt',items.reduce((a,b)=>a+Number(b.completed),0),'check','Điểm danh đã được xác nhận')}${stat('Tổng buổi học',items.reduce((a,b)=>a+Number(b.sessions),0),'calendar','Theo kế hoạch các lớp','amber')}</div><div class="welcome-band"><div><h2>Mỗi lượt điểm danh là một kết nối.</h2><p>Ghi nhận đầy đủ để cảnh báo chuyên cần luôn chính xác và cố vấn có thể hỗ trợ kịp thời.</p></div><div class="welcome-icon">${icon('cap')}</div></div><div class="between" style="margin:25px 0 18px"><h2>Lớp học của bạn</h2><a href="#/courses" class="link small">Xem tất cả →</a></div>${courseCards(items.slice(0,6))}<section class="panel" style="margin-top:25px"><div class="panel-head"><h2>Sổ buổi học</h2><p>Chọn một buổi để xem hoặc cập nhật kết quả</p></div>${sessionTable(sessions)}</section>`;}
function searchBar(placeholder){return `<div class="search-field">${icon('search')}<input id="page-search" aria-label="${placeholder}" placeholder="${placeholder}" value="${esc(state.search)}"></div>`;}
function sessionTable(rows){const filtered=rows;return filtered.length?`<div class="table-wrap"><table><thead><tr><th>MÔN HỌC / LỚP</th><th>BUỔI</th><th>NGÀY HỌC</th><th>THỜI GIAN</th><th>TRẠNG THÁI</th><th></th></tr></thead><tbody>${filtered.map(s=>`<tr><td><div class="cell-name">${esc(s.course_name)}</div><div class="cell-sub">${esc(short(s.course_offering))}</div></td><td>${num(s.session_no)}</td><td>${date(s.session_date)}</td><td class="muted">${time(s.start_time)} – ${time(s.end_time)}</td><td>${badge(s.status==='Cancelled'||s.status==='Postponed'?s.status:s.attendance_finalized?'Completed':'Scheduled',s.attendance_finalized?'Đã chốt':undefined)}</td><td><a class="btn sm" href="#/roster/${encodeURIComponent(s.name)}">${s.attendance_finalized?'Xem / sửa':'Điểm danh'} ${icon('arrow')}</a></td></tr>`).join('')}</tbody></table></div>`:empty('Không có buổi học phù hợp','Thử thay đổi bộ lọc hoặc mở trang tiếp theo.');}
function studentsTable(rows){const filtered=rows.filter(r=>state.filter==='all'||r.risk_standing===state.filter);return filtered.length?`<div class="table-wrap"><table><thead><tr><th>SINH VIÊN</th><th>CHƯƠNG TRÌNH</th><th>CỐ VẤN</th><th>CHUYÊN CẦN</th><th>TRẠNG THÁI</th><th></th></tr></thead><tbody>${filtered.map((s,i)=>`<tr><td>${nameCell(s.student_name,s.name,i)}</td><td class="muted">${esc(short(s.program))}</td><td class="muted">${esc(s.advisor_name||'Chưa phân công')}</td><td>${num(s.attendance_rate)}%</td><td>${badge(s.risk_standing||'Good')}</td><td><a class="icon-button" href="#/students/${encodeURIComponent(s.name)}" title="Hồ sơ sinh viên">${icon('chevron')}</a></td></tr>`).join('')}</tbody></table></div>`:empty('Chưa có sinh viên phù hợp');}
function pagination(data){return `<div class="table-foot between"><span>Trang ${state.page+1} · ${num(data.items?.length||0)} bản ghi</span><div class="flex">${state.page?button('← Trước','prev','sm'):''}${data.has_more?button('Tiếp →','next','sm'):''}</div></div>`;}
function studentDetail(data){const p=data.profile;return head(roles().student&&!canAdvise()?'Chuyên cần của tôi':'Hồ sơ sinh viên','Theo dõi quá trình học tập và những hỗ trợ đã được ghi nhận.',canAdvise()?'<a class="btn" href="#/students">← Danh sách sinh viên</a>'+button('Lịch sử cố vấn','support-assignment','','','data-id="'+esc(p.name)+'"'):'')+`<section class="panel"><div class="profile-hero">${avatar(p.student_name)}<div><h1>${esc(p.student_name)}</h1><div class="profile-meta"><span>${esc(short(p.name))}</span><span>${esc(p.email)}</span><span>${esc(p.phone||'Chưa cập nhật điện thoại')}</span></div></div><div style="margin-left:auto">${badge(p.risk_standing||'Good')}</div></div></section><div class="stats" style="margin-top:22px">${stat('Môn học đã đăng ký',data.enrollments.length,'book','Theo hồ sơ đăng ký')}${stat('Tỷ lệ chuyên cần',p.attendance_rate,'check','Phần trăm slot đã có mặt')}${stat('Tổng slot vắng',p.total_absent,'calendar','Các buổi đã chốt','amber')}${stat('Vắng liên tiếp',p.behavioral_absence_streak,'alert','Qua các môn trong cửa sổ theo dõi','red')}</div><div class="detail-grid"><div class="stack"><section class="panel"><div class="panel-head"><h2>Chuyên cần theo môn học</h2><p>Ngưỡng cấm thi tính trên tổng 20 slot của môn</p></div>${data.enrollments.length?`<div class="table-wrap"><table><thead><tr><th>MÔN HỌC</th><th>ĐÃ HỌC</th><th>VẮNG</th><th>CÒN ĐƯỢC NGHỈ</th><th>ĐÁNH GIÁ</th></tr></thead><tbody>${data.enrollments.map(e=>`<tr><td><div class="cell-name">${esc(e.course_name)}</div><div class="cell-sub">${esc(e.course)}</div></td><td>${num(e.completed_sessions)}/${num(e.total_sessions)}</td><td>${num(e.absent_count)} · ${num(e.absent_percentage)}%</td><td>${num(e.remaining_absences)} slot</td><td>${badge(e.attendance_standing||'Good')}</td></tr>`).join('')}</tbody></table></div>`:empty('Chưa có đăng ký học')}</section>${data.can_advise?`<section class="panel"><div class="panel-head"><h2>Hành trình đồng hành</h2><p>Nhật ký liên hệ và hỗ trợ sinh viên</p></div>${timeline(data.interventions)}</section>`:''}</div><aside class="stack"><section class="panel"><div class="panel-head"><h2>Thông tin học tập</h2></div><div class="panel-body info-list"><div><small>Chương trình đào tạo</small><strong>${esc(short(p.program))}</strong></div><div><small>Khoa</small><strong>${esc(short(p.department))}</strong></div><div><small>Ngày nhập học</small><strong>${date(p.enrollment_date)}</strong></div><div><small>Trạng thái sinh viên</small><strong>${esc(text(p.student_status))}</strong></div></div></section><section class="panel"><div class="panel-head"><h2>Lịch sử cảnh báo</h2></div><div class="panel-body stack">${data.warnings.map(w=>`<div>${data.can_advise?`<button class="link" data-action="warning" data-id="${esc(w.name)}">${badge(w.severity)}</button>`:badge(w.severity)}<p class="small muted" style="margin:8px 0">${esc(text(w.warning_type))} · ${date(w.first_detected_at)}</p>${badge(w.status)}</div>`).join('')||'<p class="small muted">Chưa có cảnh báo.</p>'}</div></section></aside></div>`;}
function rosterView(data){state.roster=data;const rows=data.students;const blocked=data.session.status==='Cancelled'||data.session.status==='Postponed'||String(data.session.session_date)>String(state.ctx.today);const counts={Present:0,Absent:0,Late:0};rows.forEach(r=>{if(counts[r.status]!==undefined)counts[r.status]++;});return head('Điểm danh buổi học',`${esc(short(data.session.course_offering))} · ${date(data.session.session_date)} · ${time(data.session.start_time)} – ${time(data.session.end_time)}`,`<a href="#/sessions/${encodeURIComponent(data.session.course_offering)}" class="btn">← Buổi học</a>`,'SỔ ĐIỂM DANH')+`<div class="stats">${stat('Sinh viên trong lớp',rows.length,'users','Theo danh sách đăng ký hợp lệ')}${stat('Có mặt',counts.Present,'check','Trong lượt điểm danh này')}${stat('Vắng mặt',counts.Absent,'alert','Trong lượt điểm danh này','red')}${stat('Đi muộn',counts.Late,'clock','Vẫn được tính có mặt','amber')}</div><div id="roster-error"></div>${blocked?'<div class="error-box">Buổi học chưa diễn ra hoặc đã hủy/hoãn. Bạn có thể xem danh sách, chưa thể chốt điểm danh.</div>':''}<section class="panel roster-panel"><div class="panel-head between"><div><h2>Ghi nhận sự hiện diện</h2><p>${data.session.attendance_finalized?'Buổi đã chốt. Khi lưu thay đổi, hệ thống sẽ kiểm tra phiên bản và tính lại cảnh báo.':'Chọn trạng thái cho từng sinh viên trước khi chốt.'}</p></div>${button('Tất cả có mặt','all-present','sm','check',blocked?'disabled':'')}</div><div class="roster-tools"><div class="search-field">${icon('search')}<input id="roster-search" aria-label="Tìm trong danh sách điểm danh" placeholder="Tìm tên hoặc mã sinh viên…" value="${esc(state.rosterSearch)}"></div><button class="btn sm" data-action="roster-pending" id="roster-pending" aria-pressed="${state.rosterOnlyPending}">Chỉ chưa điểm danh</button><span class="small muted" id="roster-visible" aria-live="polite"></span></div><div class="table-wrap"><table class="roster-table"><thead><tr><th>SINH VIÊN</th><th>ĐIỂM DANH</th><th>NGHỈ TỔNG / MÔN</th><th>CÒN ĐƯỢC NGHỈ</th><th>GHI CHÚ</th></tr></thead><tbody>${rows.map((r,i)=>`<tr data-roster-student="${esc(r.student)}" class="${['Critical','Barred'].includes(r.attendance_standing)?'at-risk':''}"><td>${nameCell(r.student_name,r.student,i)}</td><td><div class="attendance-choices">${['Present','Absent','Late'].map(status=>`<button class="choice ${status} ${r.status===status?'selected':''}" data-action="mark" data-id="${esc(r.student)}" data-status="${status}" aria-pressed="${r.status===status}" ${blocked?'disabled':''}>${text(status)}</button>`).join('')}</div><input class="late-input" type="number" min="0" max="1440" aria-label="Số phút đi muộn của ${esc(r.student_name)}" data-late="${esc(r.student)}" value="${Number(r.late_minutes||0)}" ${r.status!=='Late'?'hidden':''} ${blocked?'disabled':''}></td><td>${num(r.absent_count)}/${num(r.total_sessions)} <span class="muted small">(${num(r.absent_percentage)}%)</span><div style="margin-top:6px">${badge(r.attendance_standing||'Good')}</div></td><td>${num(r.remaining_absences)} slot</td><td><input data-remark="${esc(r.student)}" aria-label="Ghi chú của ${esc(r.student_name)}" value="${esc(r.remarks||'')}" placeholder="Ghi chú…" maxlength="2000" style="width:180px;font-size:16px" ${blocked?'disabled':''}></td></tr>`).join('')}</tbody></table></div></section><div class="roster-sticky"><div><p><strong id="marked-count">${rows.filter(r=>r.status).length}/${rows.length}</strong> sinh viên đã có trạng thái</p><span class="small muted" id="dirty-label">Số liệu chuyên cần bên trên là snapshot đã chốt.</span></div>${button('Lưu & chốt điểm danh','save-roster','primary','check',blocked?'disabled':'')}</div>`;}
function settingsView(data){const fields=[['reminder_percentage','Ngưỡng nhắc nhở (%)','Bắt đầu cảnh báo khi tỷ lệ vắng đạt mức này.'],['critical_percentage','Ngưỡng nguy hiểm (%)','Ưu tiên sinh viên cần liên hệ sớm.'],['barred_percentage','Ngưỡng cấm thi (%)','Chỉ cấm thi khi vắng vượt ngưỡng này.'],['near_limit_remaining','Số slot còn lại để nhắc nguy hiểm','Ví dụ: còn được nghỉ 1 slot thì báo nguy hiểm.'],['behavioral_consecutive_sessions','Số buổi vắng liên tiếp','Đếm liên tiếp qua mọi môn của sinh viên.'],['behavioral_window_days','Cửa sổ theo dõi (ngày)','Từ 7 đến 14 ngày lịch.']];return head('Cấu hình cảnh báo','Một bộ quy tắc thống nhất cho chuyên cần và hỗ trợ sinh viên.')+`<div class="settings-grid"><form class="panel" id="settings-form"><div class="panel-head"><h2>Ngưỡng đánh giá</h2><p>Thay đổi sẽ tính lại trạng thái và cảnh báo liên quan.</p></div><div class="panel-body field-grid">${fields.map(([key,label,help])=>`<div class="field"><label for="${key}">${label}</label><input type="number" name="${key}" id="${key}" value="${data[key]}" min="0" step="1" required><small>${help}</small></div>`).join('')}</div><div class="modal-actions"><button class="btn primary" type="submit">${icon('check')} Lưu cấu hình</button></div></form><aside class="panel"><div class="panel-head"><h2>Quy tắc hiện tại</h2></div><div class="panel-body"><span class="pill">20 slot / môn</span><p class="small muted" style="margin-top:20px">Vắng đúng 20% chưa bị cấm thi. Với ngưỡng 20%, từ slot nghỉ thứ 5 trên tổng 20 slot, sinh viên chuyển sang Cấm thi.</p><div class="success-box">Đi muộn vẫn được tính có mặt. Không có trạng thái nghỉ có phép.</div></div></aside></div>`;}
const catalogNames={'Student':'Sinh viên','Faculty Member':'Giảng viên / Cố vấn','Department':'Khoa','Program':'Ngành học','Academic Term':'Học kỳ','Course':'Môn học','Course Offering':'Lớp học phần','Class Session':'Buổi học','Student Course Enrollment':'Đăng ký học','Student Attendance':'Điểm danh','Student Warning':'Cảnh báo','Intervention Log':'Can thiệp'};
function catalogView(data){return head('Danh mục hệ thống','Quản lý dữ liệu nền tảng. Các bản ghi nghiệp vụ được bảo vệ bằng controller.',data.editable?button('Thêm bản ghi','new-record','primary','plus'):'')+`<div class="catalog-tabs">${Object.entries(catalogNames).map(([key,label])=>`<button data-action="catalog" data-doctype="${key}" class="${state.catalog===key?'active':''}">${label}</button>`).join('')}</div><div class="toolbar">${searchBar('Tìm theo mã bản ghi…')}<span class="small muted">${esc(catalogNames[data.doctype])}${data.editable?'':' · Dữ liệu nghiệp vụ chỉ xem'}</span></div><section class="panel">${data.items.length?`<div class="table-wrap"><table><thead><tr>${data.columns.map(c=>`<th>${esc(c==='name'?'Mã bản ghi':fieldLabels[c]||c.replaceAll('_',' '))}</th>`).join('')}${data.editable?'<th></th>':''}</tr></thead><tbody>${data.items.map((row,i)=>`<tr>${data.columns.map(c=>`<td>${c==='status'?badge(row[c]):esc(c==='name'?short(row[c]):row[c]??'—')}</td>`).join('')}${data.editable?`<td><button class="btn sm" data-action="edit-record" data-index="${i}">Sửa</button></td>`:''}</tr>`).join('')}</tbody></table></div>`:empty()}${pagination(data)}</section>`;}
async function route(){if(!state.ctx)return;
 if(state.lastHash!==null&&state.lastHash!==location.hash){
   if(state.modalBusy||state.rosterSaving){history.replaceState(null,'',state.lastHash);toast('Đang lưu dữ liệu. Vui lòng chờ.');return;}
   if((state.dirty||state.modalDirty)&&!confirm('Bạn có thay đổi chưa lưu. Rời trang này?')){history.replaceState(null,'',state.lastHash);return;}
   if(modal.open)modal.close();state.modalDirty=false;
 }
 clearTimeout(state.searchTimer);const [path,query='']=location.hash.replace(/^#\/?/,'').split('?');const raw=path.split('/');let routeName=raw[0]||'overview';
 const queryParams=new URLSearchParams(query);if(state.lastHash!==location.hash){state.filter=queryParams.get('status')||roleUI.defaultFilter(routeName);state.dateScope=queryParams.get('date_scope')||'all';state.page=0;if(queryParams.has('doctype')&&catalogNames[queryParams.get('doctype')])state.catalog=queryParams.get('doctype');state.lastHash=location.hash;}let id;try{id=decodeURIComponent(raw.slice(1).join('/'));}catch{id=raw.slice(1).join('/');}const view=document.querySelector('#view');const token=Symbol();state.loadToken=token;state.route=routeName;state.dirty=false;document.querySelector('.sidebar')?.classList.remove('open');document.querySelectorAll('[data-route]').forEach(a=>a.classList.toggle('active',a.dataset.route===(routeName==='roster'?'sessions':routeName)));document.querySelector('#crumb').textContent=pageNames[routeName]||'Chi tiết';view.innerHTML='<div class="boot" style="height:300px"><span class="loader"></span><span class="small">Đang lấy dữ liệu…</span></div>';try{let data,html='';
 if(routeName==='overview'){data=await request('student_crm.experience.get_workbench');html=roleUI.renderWorkbench(data);}
 else if(routeName==='courses'){data=await request('list_offerings',{search:state.search,limit_start:state.page*50,page_length:50});html=head('Lớp học phần','Tất cả lớp học trong phạm vi được phân công.')+`<div class="toolbar">${searchBar('Tìm tên môn hoặc mã lớp…')}<span class="pill">${data.items.length} lớp trong trang</span></div>`+courseCards(data.items)+pagination(data);}
 else if(routeName==='sessions'){data=await request('list_sessions',{course_offering:id||null,limit_start:state.page*100,page_length:100,attendance_filter:state.filter,search:state.search});html=head('Lịch học & điểm danh',id?esc(short(id)):'Chọn buổi học để ghi nhận chuyên cần.',roles().admin?`<a class="btn primary" href="#/catalog">${icon('plus')} Quản lý buổi học</a>`:'')+`<div class="toolbar">${searchBar('Tìm môn học, ngày học hoặc mã lớp…')}</div><section class="panel"><div id="table-area">${sessionTable(data.items)}</div>${pagination(data)}</section>`;}
 else if(routeName==='students'){if(id){data=await request('get_student_detail',{student:id});html=studentDetail(data);}else{data=await request('list_students',{search:state.search,risk_standing:state.filter,limit_start:state.page*100,page_length:100});html=head('Sinh viên',data.scoped_to_advisor?'Danh sách sinh viên được phân công cho cố vấn đang đăng nhập.':'Danh sách sinh viên toàn hệ thống.',roles().admin?button('Thêm sinh viên','add-student','primary','plus'):'')+`<div class="toolbar">${searchBar('Tìm tên hoặc mã sinh viên…')}<span class="pill">Tổng: ${num(data.total_count??data.items.length)} sinh viên</span></div><section class="panel"><div id="table-area">${studentsTable(data.items)}</div>${pagination(data)}</section>`;}}
 else if(routeName==='profile'){data=await request('get_student_detail',{student:state.ctx.student});html=studentDetail(data);}
 else if(routeName==='warnings'){data=await request('student_crm.api.get_advisor_dashboard',{limit_start:state.page*50,page_length:50});html=head('Cảnh báo sớm','Nhận diện tín hiệu rủi ro và bắt đầu một cuộc trò chuyện hỗ trợ.')+`<div class="stats">${stat(state.filter==='active'?'Cảnh báo đang hoạt động':'Cảnh báo phù hợp',data.summary.warnings.active_warnings,'alert','Trong phạm vi phụ trách')}${stat('Chưa xử lý',data.summary.warnings.open,'clock','Cần lên kế hoạch liên hệ','amber')}${stat('Đang hỗ trợ',data.summary.warnings.in_progress,'heart','Đã bắt đầu can thiệp')}${stat('Hành vi học tập',data.summary.warnings.behavioral,'trend','Vắng liên tiếp qua nhiều môn','red')}</div><section class="panel"><div class="panel-head"><h2>Danh sách cần quan tâm</h2><p>Cấm thi → Nguy hiểm → Nhắc nhở</p></div>${warningRows(data.warnings)}${pagination({items:data.warnings,has_more:data.pagination.warnings_has_more})}</section>`;}
 else if(routeName==='interventions'){data=await request('list_interventions',{limit_start:state.page*50,page_length:50});html=head('Nhật ký can thiệp','Lưu lại mỗi lần kết nối, theo dõi những chuyển biến trong học tập.')+`<section class="panel"><div class="panel-head"><h2>Những lần đồng hành</h2><p>Ghi nhật ký mới từ chi tiết một cảnh báo.</p></div>${data.items.length?`<div class="table-wrap"><table><thead><tr><th>SINH VIÊN</th><th>NỘI DUNG</th><th>KÊNH</th><th>NGÀY LIÊN HỆ</th><th>KẾT QUẢ</th><th></th></tr></thead><tbody>${data.items.map((r,i)=>`<tr><td>${nameCell(r.student_name,r.student,i)}</td><td><div style="max-width:330px;line-height:1.7">${esc(r.summary)}</div><div class="cell-sub" style="margin-top:6px">${esc(r.advisor_name)}</div></td><td>${esc(text(r.channel))}</td><td>${date(r.contacted_at)}</td><td>${badge(r.outcome,text(r.outcome))}</td><td><button class="icon-button" data-action="warning" data-id="${esc(r.warning)}" aria-label="Xem cảnh báo">${icon('chevron')}</button></td></tr>`).join('')}</tbody></table></div>`:empty('Chưa có nhật ký can thiệp')}${pagination(data)}</section>`;}
 else if(routeName==='roster'){data=await request('student_crm.api.get_session_roster',{class_session:id});html=rosterView(data);}
 else if(routeName==='settings'){data=await request('get_settings');html=settingsView(data);}
 else if(routeName==='catalog'){data=await request('get_catalog',{doctype:state.catalog,search:state.search,limit_start:state.page*50,page_length:50});html=catalogView(data);}
 else if(['cases','impact','corrections','my-attendance','notifications','quality'].includes(routeName)){html=await supportUI.render(routeName);data={};}
 else{location.hash='#/overview';return;}
 if(state.loadToken!==token)return;state.data=data;view.innerHTML=roleUI.filters(routeName)+html;enhanceRoster();refreshUnread();window.scrollTo(0,0);
 }catch(e){if(state.loadToken!==token)return;view.innerHTML=head('Chưa thể tải dữ liệu','Vui lòng kiểm tra lại quyền truy cập hoặc kết nối.')+`<div class="error-box">${esc(e.message)}</div>${button('Thử lại','refresh','','refresh')}`;if(e.status===401){login('Phiên đăng nhập đã hết hạn. Vui lòng đăng nhập lại.');}}
}
function openModal(html){state.modalDirty=false;state.modalRevision=(state.modalRevision||0)+1;modalContent.innerHTML=html;if(!modal.open)modal.showModal();return state.modalRevision;}
function closeModal(){if(state.modalBusy){toast('Đang lưu dữ liệu. Vui lòng chờ.');return false;}if(state.modalDirty&&!confirm('Biểu mẫu có thay đổi chưa lưu. Đóng biểu mẫu?'))return false;modal.close();state.modalDirty=false;return true;}
const closeButton=()=>'<button type="button" class="icon-button" data-action="close-modal" aria-label="Đóng">'+icon('close')+'</button>';
async function warningModal(id){const revision=openModal('<div class="modal-body boot" style="height:250px"><span class="loader"></span></div>');try{const data=await request('get_warning_detail',{warning:id}),w=data.warning;if(!modal.open||revision!==state.modalRevision)return;state.warning=data;openModal(`<div class="modal-head"><div class="between">${badge(w.severity)}${closeButton()}</div><h2>${esc(data.student.student_name)}</h2><div class="small muted">${esc(text(w.warning_type))} · ${esc(short(w.student))} · ${date(w.first_detected_at)}</div></div><div class="modal-body"><div class="warning-summary"><div><small>${w.warning_type==='Behavioral-Level'?'BUỔI VẮNG LIÊN TIẾP':'SLOT VẮNG'}</small><strong>${num(w.warning_type==='Behavioral-Level'?w.consecutive_sessions:w.absent_slots)}</strong></div><div><small>TỶ LỆ THEO MÔN</small><strong>${w.warning_type==='Course-Level'?num(w.absence_percentage)+'%':'Liên môn'}</strong></div><div><small>ĐIỀU KIỆN NGUY CƠ</small><strong style="font-size:16px">${w.is_active?'Đang tồn tại':'Đã hết hiệu lực'}</strong></div></div><div class="small muted" style="line-height:1.8">${w.warning_type==='Behavioral-Level'?`Sinh viên vắng ${num(w.consecutive_sessions)} buổi liên tiếp qua các môn trong cửa sổ theo dõi.`:`Sinh viên vắng ${num(w.absent_slots)}/${num(w.total_slots)} slot, còn được nghỉ ${num(w.remaining_absences)} slot.`}</div><div class="flex" style="margin-top:16px;flex-wrap:wrap"><span class="pill">${icon('mail')} ${esc(data.student.email)}</span>${data.student.phone?`<span class="pill">${esc(data.student.phone)}</span>`:''}</div><div class="section-label">TIẾN ĐỘ HỖ TRỢ</div><form id="warning-status-form" class="field-grid"><div class="field"><label>Trạng thái xử lý</label><select name="status">${['Open','In Progress','Resolved'].map(s=>`<option value="${s}" ${w.status===s?'selected':''}>${text(s)}</option>`).join('')}</select></div><div class="field"><label>Hẹn theo dõi tiếp</label><input type="date" name="next_follow_up_date" value="${esc(w.next_follow_up_date||'')}"></div><div class="field full"><label>Ghi chú của cố vấn</label><textarea name="follow_up_notes" maxlength="5000">${esc(w.follow_up_notes||'')}</textarea></div><div class="field full"><button class="btn" type="submit">Cập nhật tiến độ</button></div></form><div class="section-label">GHI NHẬN LẦN LIÊN HỆ MỚI</div><form id="intervention-form" class="field-grid"><div class="field"><label>Kênh liên hệ</label><select name="channel">${['Phone','Email','Meeting','Online','Other'].map(s=>`<option value="${s}">${text(s)}</option>`).join('')}</select></div><div class="field"><label>Kết quả liên hệ</label><select name="contact_result">${['Reached','No Response','Rescheduled'].map(s=>`<option value="${s}">${text(s)}</option>`).join('')}</select></div><div class="field full"><label>Nội dung trao đổi *</label><textarea name="summary" placeholder="Những vấn đề sinh viên đang gặp và nội dung đã trao đổi…" required maxlength="5000"></textarea></div><div class="field full"><label>Kế hoạch hỗ trợ</label><textarea name="action_plan" maxlength="5000" placeholder="Các bước hỗ trợ đã thống nhất…"></textarea></div><div class="field"><label>Kết quả theo dõi</label><select name="outcome">${['Monitoring','Pending','Improved','Escalated','Closed'].map(s=>`<option value="${s}">${text(s)}</option>`).join('')}</select></div><div class="field"><label>Ngày liên hệ tiếp</label><input type="date" name="next_follow_up_date" min="${state.ctx.today}"></div><div class="field full"><button class="btn primary" type="submit">${icon('heart')} Lưu nhật ký can thiệp</button></div></form>${data.interventions.length?'<div class="section-label">LỊCH SỬ LIÊN HỆ</div>'+timeline(data.interventions):''}</div>`);}catch(e){if(e.type==='SessionExpired'||!modal.open||revision!==state.modalRevision)return;openModal(`<div class="modal-head between"><h2>Không thể mở cảnh báo</h2>${closeButton()}</div><div class="modal-body error-box">${esc(e.message)}</div>`);}}
const fieldLabels={student_name:'Họ và tên sinh viên',id_student:'Mã sinh viên',date_of_birth:'Ngày sinh',email:'Email',phone:'Điện thoại',program:'Ngành học',admission_term:'Học kỳ nhập học',advisor:'Cố vấn',student_status:'Trạng thái sinh viên',course_code:'Mã môn học',course_name:'Tên môn học',credits:'Tín chỉ',department:'Khoa',status:'Trạng thái',course:'Môn học',academic_term:'Học kỳ',offering_code:'Mã lớp học phần',class_name:'Tên lớp',instructor:'Giảng viên',capacity:'Sĩ số',room:'Phòng học',start_date:'Ngày bắt đầu',end_date:'Ngày kết thúc',course_offering:'Lớp học phần',session_date:'Ngày học',session_no:'Số thứ tự buổi',slot_count:'Số slot',student:'Sinh viên',enrollment_date:'Ngày đăng ký',full_name:'Họ và tên',user:'Tài khoản Frappe',faculty_code:'Mã giảng viên'};
async function recordModal(index=null,data=state.data){const row=index===null?null:data.items[index];const fields=data.fields;if(!data.editable||!Array.isArray(fields))throw new Error("Không thể tải biểu mẫu. Vui lòng thử lại.");state.recordForm={doctype:data.doctype,fields,row};openModal(`<div class="modal-head between"><div><div class="eyebrow">${esc(catalogNames[data.doctype])}</div><h2>${row?'Cập nhật bản ghi':'Thêm bản ghi mới'}</h2></div>${closeButton()}</div><form id="record-form"><div class="modal-body field-grid">${fields.map(f=>{const value=row?row[f.name]:f.default==='Today'?state.ctx.today:f.default==='Now'?new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16):f.default??'';const label=fieldLabels[f.name]||f.label;const attrs=`name="${esc(f.name)}" ${f.required?'required':''}`;let control='';if(f.type==='Select')control=`<select ${attrs}>${['',...(f.options||'').split('\n')].map(o=>`<option value="${esc(o)}" ${String(value??'')===o?'selected':''}>${esc(text(o))}</option>`).join('')}</select>`;else if(f.type==='Check')control=`<input type="checkbox" name="${f.name}" ${Number(value)?'checked':''}>`;else if(['Text','Small Text','Long Text'].includes(f.type))control=`<textarea ${attrs}>${esc(value)}</textarea>`;else{const type={Date:'date',Datetime:'datetime-local',Time:'time',Int:'number',Float:'number',Percent:'number'}[f.type]||'text';control=`<input type="${type}" ${attrs} value="${esc(type==='datetime-local'?String(value||'').replace(' ','T'):type==='time'&&value?time(value):value)}" ${type==='number'?(f.type==='Int'?'step="1"':'step="any"'):''} ${f.type==='Link'?`list="link-${f.name}" data-link="${esc(f.options)}"`:''}>${f.type==='Link'?`<datalist id="link-${f.name}"></datalist><small>Liên kết: ${esc(catalogNames[f.options]||f.options)}</small>`:''}`;}return`<div class="field ${['Text','Small Text','Long Text'].includes(f.type)?'full':''}"><label>${esc(label)}${f.required?' *':''}</label>${control}</div>`;}).join('')}</div><div class="modal-actions">${button('Hủy','close-modal')}<button class="btn primary" type="submit">${icon('check')} Lưu bản ghi</button></div></form>`);const form=modal.querySelector('#record-form');await Promise.all([...modal.querySelectorAll('[data-link]')].map(async input=>{try{const options=await request('link_options',{doctype:input.dataset.link});const list=form?.querySelector('#link-'+input.name);if(list)list.innerHTML=options.map(x=>`<option value="${esc(x)}"></option>`).join('');}catch(e){if(e.type==='SessionExpired')throw e;}}));}
function dirty(){state.dirty=true;const el=document.querySelector('#dirty-label');if(el)el.textContent='Có thay đổi chưa lưu. Chốt điểm danh để cập nhật hệ thống.';const count=document.querySelector('#marked-count');if(count)count.textContent=`${state.roster.students.filter(r=>r.status).length}/${state.roster.students.length}`;}
const busyActions=new WeakSet();
async function action(el){if(busyActions.has(el))return;busyActions.add(el);const a=el.dataset.action;try{
 if(state.modalDirty&&['warning','support-case','support-correction'].includes(a)){if(!confirm('Biểu mẫu có thay đổi chưa lưu. Tiếp tục mở nội dung khác?'))return;state.modalDirty=false;}
 if(a==='roster-pending'){state.rosterOnlyPending=!state.rosterOnlyPending;applyRosterFilter();return;}
 if(a.startsWith('support-')){await supportUI.action(el);return;}
 if(a==='logout'){if(state.rosterSaving){toast('Đang lưu điểm danh. Vui lòng chờ.');return;}if(state.dirty&&!confirm('Bạn có thay đổi chưa lưu. Đăng xuất?'))return;await request('logout',{},'POST');state.dirty=false;location.hash='';login();}
 else if(a==='menu')document.querySelector('.sidebar').classList.toggle('open');
 else if(a==='password'){const p=document.querySelector('#password');p.type=p.type==='password'?'text':'password';}
 else if(a==='demo'){document.querySelector('#email').value=el.dataset.user;document.querySelector('#password').focus();}
 else if(a==='refresh'){if(state.dirty&&!confirm('Tải lại sẽ bỏ thay đổi chưa lưu. Tiếp tục?'))return;await route();}
 else if(a==='next'||a==='prev'){state.page+=a==='next'?1:-1;await route();}
 else if(a==='close-modal')closeModal();
 else if(a==='warning')await warningModal(el.dataset.id);
 else if(a==='catalog'){state.catalog=el.dataset.doctype;state.page=0;state.search='';await route();}
 else if(a==='new-record')await recordModal();
 else if(a==='edit-record')await recordModal(Number(el.dataset.index));
 else if(a==='add-student'){el.disabled=true;try{const data=await request('get_catalog',{doctype:'Student',page_length:1});await recordModal(null,data);}finally{el.disabled=false;}}
 else if(a==='mark'){const row=state.roster.students.find(r=>r.student===el.dataset.id);row.status=el.dataset.status;if(row.status!=='Late')row.late_minutes=0;el.parentElement.querySelectorAll('button').forEach(b=>{b.classList.toggle('selected',b.dataset.status===row.status);b.setAttribute('aria-pressed',String(b.dataset.status===row.status));});const input=el.closest('td').querySelector('[data-late]');input.hidden=row.status!=='Late';input.value=row.late_minutes||0;dirty();applyRosterFilter();}
 else if(a==='all-present'){state.roster.students.forEach(r=>{r.status='Present';r.late_minutes=0;});document.querySelector('#view').innerHTML=rosterView(state.roster);enhanceRoster();dirty();}
 else if(a==='save-roster'){const rows=state.roster.students;if(rows.some(r=>!r.status)){toast('Vui lòng chọn trạng thái cho tất cả sinh viên.',true);return;}state.rosterSaving=true;el.disabled=true;el.textContent='Đang lưu & cập nhật cảnh báo…';try{const saved=await request('student_crm.api.submit_bulk_attendance',{class_session:state.roster.session.name,expected_modified:state.roster.session.modified,attendance_data:rows.map(r=>({student:r.student,status:r.status,late_minutes:r.status==='Late'?Number(r.late_minutes||0):0,remarks:r.remarks||''}))},'POST');state.dirty=false;state.data=saved;document.querySelector('#view').innerHTML=rosterView(saved);enhanceRoster();toast(saved.idempotent?'Kết quả đã được chốt, không có thay đổi mới.':'Đã chốt điểm danh và cập nhật cảnh báo.');}catch(e){if(e.type==='SessionExpired')throw e;const errorBox=document.querySelector('#roster-error');if(errorBox)errorBox.innerHTML=`<div class="error-box">${esc(e.message)}${e.type==='TimestampMismatchError'?'<br>Hãy tải lại và đối chiếu kết quả trước khi lưu.':''}</div>`;throw e;}finally{state.rosterSaving=false;el.disabled=false;el.innerHTML=icon('check')+' Lưu & chốt điểm danh';}}
 }catch(e){if(e.type!=='SessionExpired')toast(e.message,true);}finally{busyActions.delete(el);}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el){e.preventDefault();action(el);}const link=e.target.closest('a[href^="#/"]');if(link){if(state.modalBusy||state.rosterSaving){e.preventDefault();toast('Đang lưu dữ liệu. Vui lòng chờ.');return;}if((state.dirty||state.modalDirty)&&!confirm('Bạn có thay đổi chưa lưu. Rời trang này?')){e.preventDefault();return;}state.dirty=false;state.modalDirty=false;clearTimeout(state.searchTimer);state.search='';state.filter='all';state.page=0;if(link.getAttribute('href')===location.hash){e.preventDefault();state.lastHash=null;route();}}});
document.addEventListener('input',e=>{if(modal.contains(e.target))state.modalDirty=true;if(e.target.closest?.('#settings-form'))state.dirty=true;if(e.target.id==='roster-search'){state.rosterSearch=e.target.value;applyRosterFilter();return;}if(e.target.dataset.late){const row=state.roster.students.find(r=>r.student===e.target.dataset.late);row.late_minutes=Number(e.target.value);dirty();}if(e.target.dataset.remark){state.roster.students.find(r=>r.student===e.target.dataset.remark).remarks=e.target.value;dirty();}if(e.target.id==='page-search'){state.search=e.target.value;{clearTimeout(state.searchTimer);state.searchTimer=setTimeout(async()=>{const caret=state.search.length;state.page=0;await route();const input=document.querySelector('#page-search');input?.focus();input?.setSelectionRange(caret,caret);},450);}}});
document.addEventListener('change',e=>{if(modal.contains(e.target))state.modalDirty=true;if(e.target.id==='term-filter'){if(state.dirty&&!confirm('Đổi học kỳ sẽ bỏ thay đổi chưa lưu. Tiếp tục?')){e.target.value=state.term;return;}state.term=e.target.value;state.page=0;route();return;}if(e.target.id==='date-filter'){state.dateScope=e.target.value;state.page=0;syncFilterQuery('date_scope',state.dateScope);route();return;}if(e.target.id==='page-filter'){state.filter=e.target.value;state.page=0;syncFilterQuery('status',state.filter);route();}});
const busyForms=new WeakSet();
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target;if(busyForms.has(form))return;const inModal=modal.contains(form);if(inModal&&state.modalBusy)return;busyForms.add(form);if(inModal)state.modalBusy=(state.modalBusy||0)+1;const submit=form.querySelector('[type=submit]');if(submit)submit.disabled=true;try{const data=Object.fromEntries(new FormData(form));
 if(form.id.startsWith('support-')){await supportUI.submit(form,data);}
 else if(form.id==='login-form'){document.querySelector('#login-error').textContent='';await request('login',data,'POST');state.ctx=await request('get_context');state.terms=(await request('student_crm.experience.get_terms')).items;state.term='';state.lastHash=null;form.reset();shell();if(!canAdvise()&&!roles().instructor)document.querySelector('#global-search')?.remove();await navigate('#/overview');}
 else if(form.id==='global-search'){state.search=form.querySelector('input').value;state.page=0;await navigate(canAdvise()?'#/students':'#/courses');}
 else if(form.id==='intervention-form'){await request('save_intervention',{warning:state.warning.warning.name,...data},'POST');modal.close();toast('Đã ghi nhận lần hỗ trợ sinh viên.');await route();}
 else if(form.id==='warning-status-form'){await request('update_warning',{warning:state.warning.warning.name,expected_modified:String(state.warning.warning.modified),...data},'POST');modal.close();toast('Đã cập nhật tiến độ hỗ trợ.');await route();}
 else if(form.id==='settings-form'){for(const key of Object.keys(data))data[key]=Number(data[key]);await request('save_settings',{data},'POST');toast('Đã lưu cấu hình và tính lại cảnh báo.');await route();}
 else if(form.id==='record-form'){const record=state.recordForm;if(!record)throw new Error('Biểu mẫu đã hết hạn. Vui lòng mở lại.');for(const field of record.fields){if(field.type==='Check')data[field.name]=form.elements[field.name].checked?1:0;else if(['Int','Float','Percent'].includes(field.type)&&data[field.name]!=='')data[field.name]=Number(data[field.name]);}await request('save_record',{doctype:record.doctype,name:record.row?.name||null,expected_modified:record.row?.modified||null,data},'POST');modal.close();toast('Đã lưu bản ghi.');await route();}
 }catch(error){if(error.type==='SessionExpired')return;if(form.id==='login-form'){const friendly=['AuthenticationError','LoginFailed'].includes(error.type)?'Tài khoản hoặc mật khẩu chưa chính xác.':error.message;document.querySelector('#login-error').textContent=friendly;}else toast(error.message,true);}finally{busyForms.delete(form);if(inModal)state.modalBusy=Math.max(0,(state.modalBusy||0)-1);if(submit)submit.disabled=false;}});
function attachLabels(){document.querySelectorAll('.field').forEach((field,i)=>{const label=field.querySelector('label'),control=field.querySelector('input,select,textarea');if(label&&control&&!label.htmlFor){control.id||=`field-${crypto.randomUUID()}`;label.htmlFor=control.id;}});}
new MutationObserver(()=>attachLabels()).observe(app,{childList:true,subtree:true});
new MutationObserver(()=>attachLabels()).observe(modalContent,{childList:true,subtree:true});
document.addEventListener('click',()=>{if(state.roster&&state.route==='roster')setTimeout(()=>{const counters={'Có mặt':'Present','Vắng mặt':'Absent','Đi muộn':'Late'};for(const[label,status]of Object.entries(counters)){const el=document.querySelector(`[data-stat="${label}"]`);if(el)el.textContent=state.roster.students.filter(r=>r.status===status).length;}},0);});
window.addEventListener('hashchange',()=>route());window.addEventListener('beforeunload',e=>{if(state.dirty||state.modalDirty||state.modalBusy||state.rosterSaving){e.preventDefault();e.returnValue='';}});
modal.addEventListener('click',e=>{if(e.target===modal)closeModal();});
modal.addEventListener('cancel',e=>{e.preventDefault();closeModal();});
modal.addEventListener('close',()=>{state.modalDirty=false;state.modalRevision=(state.modalRevision||0)+1;});
