const roleUI=createRoleUI({state,esc,head,stat,icon,date,time,num,badge,empty,sessionTable});
const supportUI=createSupportUI({request,esc,icon,badge,head,stat,empty,date,num,button,state,roles,openModal,closeButton,toast,refresh:route,showWarning:warningModal});
function enhanceRoster(){
 if(state.route!=='roster'||!state.roster)return;
 const labels=['Sinh viên','Điểm danh','Chuyên cần theo môn','Còn được nghỉ','Ghi chú'];
 document.querySelectorAll('.roster-table tbody tr').forEach(row=>[...row.cells].forEach((cell,i)=>cell.dataset.label=labels[i]));
 applyRosterFilter();
}
function applyRosterFilter(){
 if(state.route!=='roster'||!state.roster)return;
 let visible=0;const query=state.rosterSearch.trim().toLocaleLowerCase('vi');
 const records=new Map(state.roster.students.map(r=>[r.student,r]));
 document.querySelectorAll('[data-roster-student]').forEach(row=>{const r=records.get(row.dataset.rosterStudent);if(!r)return;const show=(!state.rosterOnlyPending||!r.status)&&(`${r.student_name} ${r.student}`.toLocaleLowerCase('vi').includes(query));row.hidden=!show;if(show)visible++;});
 const label=document.querySelector('#roster-visible');if(label)label.textContent=`Hiển thị ${visible}/${state.roster.students.length} sinh viên`;
 const toggle=document.querySelector('#roster-pending');if(toggle){toggle.setAttribute('aria-pressed',String(state.rosterOnlyPending));toggle.classList.toggle('active',state.rosterOnlyPending);}
}
let unreadBusy=false;
async function refreshUnread(){
 if(!state.ctx||unreadBusy||document.hidden)return;unreadBusy=true;const user=state.ctx.user;
 try{const d=await request('student_crm.experience.unread_count');if(state.ctx?.user!==user)return;document.querySelectorAll('[data-unread]').forEach(el=>{el.hidden=!d.unread;el.textContent=d.unread>99?'99+':String(d.unread);});document.querySelector('.notification-bell')?.setAttribute('aria-label',`Thông báo, ${d.unread} chưa đọc`);}catch{}finally{unreadBusy=false;}
}
if(typeof setInterval==='function')setInterval(refreshUnread,30000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshUnread();});
let sessionProbe=null;
async function sessionIsActive(){
 if(!sessionProbe)sessionProbe=fetch('/api/method/student_crm.portal.get_context',{credentials:'same-origin',headers:{Accept:'application/json'}}).then(r=>![401,403].includes(r.status)).catch(()=>true).finally(()=>{sessionProbe=null;});
 return sessionProbe;
}
function expireSession(){if(modal.open)modal.close();login('Phiên đăng nhập đã hết hạn. Vui lòng đăng nhập lại. Những thay đổi chưa lưu chưa được gửi.');}
function syncFilterQuery(key,value){const [path,query='']=location.hash.split('?');const params=new URLSearchParams(query);params.set(key,value);history.replaceState(null,'',path+'?'+params.toString());state.lastHash=location.hash;}
async function navigate(hash){if(location.hash===hash){state.lastHash=null;await route();}else location.hash=hash;}
boot();
